<?php declare(strict_types=1);require_once __DIR__.'/_common.php';$keys=['site_name','site_full_name','site_tagline','address','phone','email','social_facebook','social_instagram','social_youtube','map_embed_url','home_welcome','home_intro','about_history','about_mission','about_values',
