'translation_api_url','translation_api_key'];if(post()){verifyCsrf();foreach($keys as $k){db()->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,clean($k,10000)]);}adminAudit('update','site_settings');flash('success','Site content and contact settings saved.');redirect('settings.php');}$settings=[];foreach(db()->query('SELECT setting_key,setting_value FROM site_settings')->fetchAll() as $r)$settings[$r['setting_key']]=$r['setting_value'];$pageTitle='Site settings';if(trim((string)($settings['translation_api_url']??''))==='' || (($settings['translation_api_url']??'')==='https://libretranslate.com/translate'&&trim((string)($settings['translation_api_key']??''))==='') || (($settings['translation_api_url']??'')==='https://translate.argosopentech.com/translate'&&trim((string)($settings['translation_api_key']??''))===''))$settings['translation_api_url']='https://translate.cutie.dating/translate';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Administration</p><h1 class="section-title">Site settings & public pages.</h1><form class="form-shell" style="max-width:none" method="post"><?=csrfField()?><div class="grid-3"><?php foreach($keys as $k):?><div class="field"><label><?=e(ucwords(str_replace('_',' ',$k)))?></label><?php if(in_array($k,['home_intro','about_history','about_mission','about_values','home_hero_note_one_text','home_hero_note_two_text','home_trust_line','home_projects_intro','home_news_intro','home_events_intro','home_cta_intro','about_intro','about_purpose_text','about_cta_text','projects_intro','news_intro','events_intro','gallery_intro','contact_intro','contact_form_hint'],true)):?><textarea name="<?=$k?>"><?=e($settings[$k]??'')?></textarea><?php else:?><input name="<?=$k?>" value="<?=e($settings[$k]??'')?>" <?=in_array($k,['email'],true)?'type="email"':''?>><?php endif;?></div><?php endforeach;?></div><div class="translation-provider-help"><strong>Translation provider</strong><p>Use a LibreTranslate-compatible <code>/translate</code> endpoint. The browser tries the saved server provider first, then falls back to the current public community mirrors if the PHP host cannot reach it. Public mirrors can go offline; for production, use your own LibreTranslate instance or a provider with a stable API key. The connection test below tests both paths.</p><button class="btn ghost" type="button" data-translation-test>Test saved translation connection</button><p class="help" data-translation-test-result aria-live="polite"></p></div><button class="btn primary">Save all settings</button></form></div><script>document.querySelector("[data-translation-test]")?.addEventListener("click",async()=>{const result=document.querySelector("[data-translation-test-result]");const button=document.querySelector("[data-translation-test]");result.textContent="Testing the saved provider and browser fallback…";button.disabled=true;try{const api=document.querySelector('meta[name="translation-api"]')?.content;const service=window.ATACJLTranslation;if(!service)throw new Error("Translation helper did not load. Reload the page and try again.");const data=await service.translateTexts(["ATACJL translation connection test"],"fr",api);result.textContent="Connected via "+data.provider+": "+data.translatedTexts[0];}catch(error){result.textContent="Translation test failed: "+(error instanceof Error?error.message:"provider unavailable")+". Configure an available LibreTranslate endpoint or API key and try again.";}finally{button.disabled=false;}});</script></div></section><?php require dirname(__DIR__).'/includes/footer.php';
